local A=IAHelper local LHAS=LibHarvensAddonSettings function A.BuildMenu(SV,defaults) local options={allowDefaults=true,allowRefresh=true,} local settings=LHAS:AddAddon("Infinite Archive Helper",options) local maxX,maxY=GuiRoot:GetDimensions() maxX=math.floor(maxX) maxY=math.floor(maxY) local scene local IAHelperinMenu=false local function addIAHelperUItoMenu() if IAHelperinMenu then return end scene=SCENE_MANAGER:GetCurrentScene() for _,fragment in pairs(A.fragments) do scene:AddFragment(fragment) end IAHelperinMenu=true end local function addonSelected(_,addonSettings) local isIAHelper=addonSettings==settings if not isIAHelper and IAHelperinMenu then for _,fragment in pairs(A.fragments) do scene:RemoveFragment(fragment) fragment:Refresh() end IAHelperinMenu=false end end CALLBACK_MANAGER:RegisterCallback("LibHarvensAddonSettings_AddonSelected",addonSelected) settings:AddSettings({{type=LHAS.ST_SECTION,label="|cFFFACDGeneral|r",},{type=LHAS.ST_CHECKBOX,label="Enable Data Sharing",tooltip="When duo,allows to see other player's verses and visions choices. Requires |cFFFF00LibDataShare|r to work.",default=defaults.enableDataSharing,getFunction=function() return SV.enableDataSharing end,setFunction=function(value) SV.enableDataSharing=value or false end,},{type=LHAS.ST_CHECKBOX,label="Enable Sounds",tooltip="Play sounds for incoming attacks.",default=defaults.enableSounds,getFunction=function() return SV.enableSounds end,setFunction=function(value) SV.enableSounds=value or false end,},{type=LHAS.ST_CHECKBOX,label="Track incoming attacks",tooltip=string.format("Show timers for incoming attacks. Most of them are colored |c%syellow|r,but the most dangerous ones are |c%sred|r. |c%sGreen|r color usually means you should move out of some area,and |c%sblue|r must be blocked. There are some other colors to help distinguish different attacks on bosses,and usually it's up to you if you prefer to block or dodge them.",IA_COLOR_YELLOW,IA_COLOR_RED,IA_COLOR_GREEN,IA_COLOR_BLUE),default=defaults.enableTimers,getFunction=function() return SV.enableTimers end,setFunction=function(value) SV.enableTimers=value or false end,},{type=LHAS.ST_CHECKBOX,label="Track spawns",tooltip="Notify when dangerous enemies spawn.",default=defaults.enableWave,getFunction=function() return SV.enableWave end,setFunction=function(value) SV.enableWave=value or false end,},{type=LHAS.ST_CHECKBOX,label="Enable markers",tooltip="Automatically place markers on dangerous mobs (solo or group leader only). You need to target them first,which means there is a (small) chance a wrong unit will be marked if it's in the way.",default=defaults.enableMarkers,getFunction=function() return SV.enableMarkers end,setFunction=function(value) SV.enableMarkers=value or false end,},{type=LHAS.ST_CHECKBOX,label="Track Weakening Enchantment",tooltip="Show weapon damage reduction on bosses.",default=defaults.enableWeakening,getFunction=function() return SV.enableWeakening end,setFunction=function(value) SV.enableWeakening=value or false end,},{type=LHAS.ST_CHECKBOX,label="Track Major Cowardice",tooltip="The only tracked source for now is nightblade's Mass Hysteria skill.",default=defaults.enableMajorCowardice,getFunction=function() return SV.enableMajorCowardice end,setFunction=function(value) SV.enableMajorCowardice=value or false end,},{type=LHAS.ST_CHECKBOX,label="Track Scorching Support",tooltip="Show cooldown for Scorching Support vision.",default=defaults.enableScorchingSupport,getFunction=function() return SV.enableScorchingSupport end,setFunction=function(value) SV.enableScorchingSupport=value or false end,},{type=LHAS.ST_CHECKBOX,label="Enable Castbar",tooltip="Currently only shows Storm Imps' channeled casts. Note: after arc 8 they become instant.",default=defaults.enableCastbar,getFunction=function() return SV.enableCastbar end,setFunction=function(value) SV.enableCastbar=value or false end,},{type=LHAS.ST_CHECKBOX,label="Hide stage announcement",tooltip="Hide default screen announcement at the beginning of every stage to reduce screen clutter.",default=defaults.hideStageAnnouncement,getFunction=function() return SV.hideStageAnnouncement end,setFunction=function(value) SV.hideStageAnnouncement=value or false end,requiresReload=true,},{type=LHAS.ST_SECTION,label="|cFFFACDMisc|r",},{type=LHAS.ST_CHECKBOX,label="Debug Mode",tooltip="Display internal events in the game chat.",default=false,getFunction=function() return A.IsDebugMode() end,setFunction=function(value) A.SetDebugMode(value or false) end,},{type=LHAS.ST_SECTION,label="|cFFFACDUI Movement|r",},{type=LHAS.ST_CHECKBOX,label="UI Locked",tooltip="Unlock UI to reposition notifications.",default=true,setFunction=function(value) if not IAHelperinMenu then addIAHelperUItoMenu() else addonSelected() end A.ToggleUI(value) end,getFunction=function() return A.uiLocked end,},{type=LHAS.ST_LABEL,label="Reticle",},{type=LHAS.ST_SLIDER,label="Left <- -> Right",tooltip="Default is "..maxX/2,setFunction=function(value) SV.reticleCenterX=value A.SetControlAnchor(IAHelper_Reticle,CENTER,SV.reticleCenterX,SV.reticleCenterY) end,getFunction=function() return SV.reticleCenterX or maxX/2 end,default=maxX/2,min=0,max=maxX,step=5},{type=LHAS.ST_SLIDER,label="Up <- -> Down",tooltip="Default: "..maxY/2,setFunction=function(value) SV.reticleCenterY=value A.SetControlAnchor(IAHelper_Reticle,CENTER,SV.reticleCenterX,SV.reticleCenterY) end,getFunction=function() return SV.reticleCenterY or maxY/2 end,default=maxY/2,min=0,max=maxY,step=5},{type=LHAS.ST_LABEL,label="ABILITY 1",},{type=LHAS.ST_SLIDER,label="Left <- -> Right",tooltip="Default is "..maxX/2,setFunction=function(value) SV.win1CenterX=value A.SetControlAnchor(IAHelper_Win1,CENTER,value,SV.win1CenterY) end,getFunction=function() return SV.win1CenterX or maxX/2 end,default=maxX/2,min=0,max=maxX,step=5},{type=LHAS.ST_SLIDER,label="Up <- -> Down",tooltip="Default: "..(maxY/2)-200,setFunction=function(value) SV.win1CenterY=value A.SetControlAnchor(IAHelper_Win1,CENTER,SV.win1CenterX,value) end,getFunction=function() return SV.win1CenterY or (maxY/2)-200 end,default=(maxY/2)-200,min=0,max=maxY,step=5},{type=LHAS.ST_LABEL,label="ABILITY 2",},{type=LHAS.ST_CHECKBOX,label="Show ABILITY 2",tooltip="Display ABILITY 2.",default=defaults.Win2Enabled,getFunction=function() return SV.Win2Enabled end,setFunction=function(value) SV.Win2Enabled=value if value==false then A.HideWin2() end end,},{type=LHAS.ST_SLIDER,label="Left <- -> Right",tooltip="Default is "..(maxX/2),setFunction=function(value) SV.win2CenterX=value A.SetControlAnchor(IAHelper_Win2,CENTER,SV.win2CenterX,SV.win2CenterY) end,getFunction=function() return SV.win2CenterX or (maxX/2) end,default=(maxX/2),min=0,max=maxX,step=5},{type=LHAS.ST_SLIDER,label="Up <- -> Down",tooltip="Default: "..(maxY/2)-270,setFunction=function(value) SV.win2CenterY=value A.SetControlAnchor(IAHelper_Win2,CENTER,SV.win2CenterX,SV.win2CenterY) end,getFunction=function() return SV.win2CenterY or (maxY/2)-270 end,default=(maxY/2)-270,min=0,max=maxY,step=5},{type=LHAS.ST_LABEL,label="Wave Info",},{type=LHAS.ST_SLIDER,label="Left <- -> Right",tooltip="Default is "..(maxX/2),setFunction=function(value) SV.waveCenterX=value A.SetControlAnchor(IAHelper_Wave,CENTER,SV.waveCenterX,SV.waveCenterY) end,getFunction=function() return SV.waveCenterX or (maxX/2) end,default=(maxX/2),min=0,max=maxX,step=5},{type=LHAS.ST_SLIDER,label="Up <- -> Down",tooltip="Default: "..(maxY/2)+200,setFunction=function(value) SV.waveCenterY=value A.SetControlAnchor(IAHelper_Wave,CENTER,SV.waveCenterX,SV.waveCenterY) end,getFunction=function() return SV.waveCenterY or (maxY/2)+200 end,default=(maxY/2)+200,min=0,max=maxY,step=5},{type=LHAS.ST_LABEL,label="Cast Bar",},{type=LHAS.ST_SLIDER,label="Left <- -> Right",tooltip="Default is "..(maxX/2),setFunction=function(value) SV.castbarCenterX=value A.SetControlAnchor(IAHelper_Castbar,CENTER,SV.castbarCenterX,SV.castbarCenterY) end,getFunction=function() return SV.castbarCenterX or (maxX/2) end,default=(maxX/2),min=0,max=maxX,step=5},{type=LHAS.ST_SLIDER,label="Up <- -> Down",tooltip="Default: "..(maxY/2)+65,setFunction=function(value) SV.castbarCenterY=value A.SetControlAnchor(IAHelper_Castbar,CENTER,SV.castbarCenterX,SV.castbarCenterY) end,getFunction=function() return SV.castbarCenterY or (maxY/2)+65 end,default=(maxY/2)+65,min=0,max=maxY,step=5},{type=LHAS.ST_LABEL,label="Major Cowardice",},{type=LHAS.ST_SLIDER,label="Left <- -> Right",tooltip="Default is "..(maxX/2)+250,setFunction=function(value) SV.majorCowardiceLeft=value A.SetControlAnchor(IAHelper_MajorCowardice,TOPLEFT,SV.majorCowardiceLeft,SV.majorCowardiceTop) end,getFunction=function() return SV.majorCowardiceLeft or (maxX/2)+250 end,default=(maxX/2)+250,min=0,max=maxX,step=5},{type=LHAS.ST_SLIDER,label="Up <- -> Down",tooltip="Default: "..(maxY/2)+210,setFunction=function(value) SV.majorCowardiceTop=value A.SetControlAnchor(IAHelper_MajorCowardice,TOPLEFT,SV.majorCowardiceLeft,SV.majorCowardiceTop) end,getFunction=function() return SV.majorCowardiceTop or (maxY/2)+210 end,default=(maxY/2)+210,min=0,max=maxY,step=5},{type=LHAS.ST_LABEL,label="Scorching Support",},{type=LHAS.ST_SLIDER,label="Left <- -> Right",tooltip="Default is "..(maxX/2)+250,setFunction=function(value) SV.scorchingSupportLeft=value A.SetControlAnchor(IAHelper_ScorchingSupport,TOPLEFT,SV.scorchingSupportLeft,SV.scorchingSupportTop) end,getFunction=function() return SV.scorchingSupportLeft or (maxX/2)+250 end,default=(maxX/2)+250,min=0,max=maxX,step=5},{type=LHAS.ST_SLIDER,label="Up <- -> Down",tooltip="Default: "..(maxY/2)+50,setFunction=function(value) SV.scorchingSupportTop=value A.SetControlAnchor(IAHelper_ScorchingSupport,TOPLEFT,SV.scorchingSupportLeft,SV.scorchingSupportTop) end,getFunction=function() return SV.scorchingSupportTop or (maxY/2)+50 end,default=(maxY/2)+50,min=0,max=maxY,step=5},{type=LHAS.ST_LABEL,label="Weakening",},{type=LHAS.ST_SLIDER,label="Left <- -> Right",tooltip="Default is "..(maxX/2)+205,setFunction=function(value) SV.weakeningLeft=value A.SetControlAnchor(IAHelper_Weakening,TOPLEFT,SV.weakeningLeft,SV.weakeningTop) end,getFunction=function() return SV.weakeningLeft or (maxX/2)+205 end,default=(maxX/2)+205,min=0,max=maxX,step=5},{type=LHAS.ST_SLIDER,label="Up <- -> Down",tooltip="Default: "..(maxY/2)-95,setFunction=function(value) SV.weakeningTop=value A.SetControlAnchor(IAHelper_Weakening,TOPLEFT,SV.weakeningLeft,SV.weakeningTop) end,getFunction=function() return SV.weakeningTop or (maxY/2)-95 end,default=(maxY/2)-95,min=0,max=maxY,step=5},{type=LHAS.ST_SECTION,label="Major Cowardice Advance",},{type=LHAS.ST_SLIDER,label="BG Size X",tooltip="Default: "..defaults.majorCowardiceSettings.bg.w,setFunction=function(value) SV.majorCowardiceSettings.bg.w=value IAHelper_MajorCowardice:SetDimensions(SV.majorCowardiceSettings.bg.w,SV.majorCowardiceSettings.bg.h) IAHelper_MajorCowardice_BG:SetDimensions(SV.majorCowardiceSettings.bg.w,SV.majorCowardiceSettings.bg.h) end,getFunction=function() return SV.majorCowardiceSettings.bg.w end,default=defaults.majorCowardiceSettings.bg.w,min=100,max=1000,step=5},{type=LHAS.ST_SLIDER,label="BG Size Y",tooltip="Default: "..defaults.majorCowardiceSettings.bg.h,setFunction=function(value) SV.majorCowardiceSettings.bg.h=value IAHelper_MajorCowardice:SetDimensions(SV.majorCowardiceSettings.bg.w,SV.majorCowardiceSettings.bg.h) IAHelper_MajorCowardice_BG:SetDimensions(SV.majorCowardiceSettings.bg.w,SV.majorCowardiceSettings.bg.h) end,getFunction=function() return SV.majorCowardiceSettings.bg.h end,default=defaults.majorCowardiceSettings.bg.h,min=20,max=300,step=5},{type=LHAS.ST_SLIDER,label="Icon Size",tooltip="Default: "..defaults.majorCowardiceSettings.icon.size,setFunction=function(value) SV.majorCowardiceSettings.icon.size=value IAHelper_MajorCowardice_Icon:SetDimensions(value,value) end,getFunction=function() return SV.majorCowardiceSettings.icon.size end,default=defaults.majorCowardiceSettings.icon.size,min=20,max=150,step=1},{type=LHAS.ST_SLIDER,label="Icon X offset",tooltip="Default: "..defaults.majorCowardiceSettings.icon.x,setFunction=function(value) SV.majorCowardiceSettings.icon.x=value A.SetControlAnchor(IAHelper_MajorCowardice_Icon,LEFT,SV.majorCowardiceSettings.icon.x,SV.majorCowardiceSettings.icon.y,IAHelper_MajorCowardice,TOPLEFT) end,getFunction=function() return SV.majorCowardiceSettings.icon.x end,default=defaults.majorCowardiceSettings.icon.x,min=20,max=100,step=1},{type=LHAS.ST_SLIDER,label="Icon Y offset",tooltip="Default: "..defaults.majorCowardiceSettings.icon.y,setFunction=function(value) SV.majorCowardiceSettings.icon.y=value A.SetControlAnchor(IAHelper_MajorCowardice_Icon,LEFT,SV.majorCowardiceSettings.icon.x,SV.majorCowardiceSettings.icon.y,IAHelper_MajorCowardice,TOPLEFT) end,getFunction=function() return SV.majorCowardiceSettings.icon.y end,default=defaults.majorCowardiceSettings.icon.y,min=-20,max=150,step=1},{type=LHAS.ST_SLIDER,label="Title Font Size",tooltip="Default: "..defaults.majorCowardiceSettings.title.font,setFunction=function(value) SV.majorCowardiceSettings.title.font=value IAHelper_MajorCowardice_Num:SetFont("$(BOLD_FONT)|$(KB_"..SV.majorCowardiceSettings.title.font..")|soft-shadow-thick") end,getFunction=function() return SV.majorCowardiceSettings.title.font end,default=defaults.majorCowardiceSettings.title.font,min=10,max=54,step=1},{type=LHAS.ST_SLIDER,label="Title X offset",tooltip="Default: "..defaults.majorCowardiceSettings.title.x,setFunction=function(value) SV.majorCowardiceSettings.title.x=value A.SetControlAnchor(IAHelper_MajorCowardice_Num,TOPLEFT,SV.majorCowardiceSettings.title.x,SV.majorCowardiceSettings.title.y,IAHelper_MajorCowardice,TOPLEFT) end,getFunction=function() return SV.majorCowardiceSettings.title.x end,default=defaults.majorCowardiceSettings.title.x,min=10,max=250,step=5},{type=LHAS.ST_SLIDER,label="Title Y offset",tooltip="Default: "..defaults.majorCowardiceSettings.title.y,setFunction=function(value) SV.majorCowardiceSettings.title.y=value A.SetControlAnchor(IAHelper_MajorCowardice_Num,TOPLEFT,SV.majorCowardiceSettings.title.x,SV.majorCowardiceSettings.title.y,IAHelper_MajorCowardice,TOPLEFT) end,getFunction=function() return SV.majorCowardiceSettings.title.y end,default=defaults.majorCowardiceSettings.title.y,min=-50,max=100,step=1},{type=LHAS.ST_SLIDER,label="Text Font Size",tooltip="Default: "..defaults.majorCowardiceSettings.text.font,setFunction=function(value) SV.majorCowardiceSettings.text.font=value IAHelper_MajorCowardice_Text:SetFont("$(MEDIUM_FONT)|$(KB_"..SV.majorCowardiceSettings.text.font..")|soft-shadow-thin") end,getFunction=function() return SV.majorCowardiceSettings.text.font end,default=defaults.majorCowardiceSettings.text.font,min=10,max=54,step=1},}) end